import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { RouterModule } from '@angular/router';
import { FormsModule } from '@angular/forms';
import { ApiService } from '../../core/services/api.service';
import { ToastService } from '../../core/services/toast.service';

@Component({
  selector: 'app-analysis',
  standalone: true,
  imports: [CommonModule, RouterModule, FormsModule],
  template: `
    <div class="page-container">
      <div class="page-header">
        <h1 class="page-title">// analyses_ia</h1>
        <p class="page-subtitle">Rapports générés par les agents IA — Root Cause, Security, Remediation, Judge</p>
      </div>

      <!-- Agent filter tabs -->
      <div class="agent-tabs" style="margin-bottom:16px;">
        <button *ngFor="let t of tabs" class="agent-tab"
                [class.active]="activeTab === t.key"
                [style.--tab-color]="t.color"
                (click)="activeTab = t.key; load()">
          <span>{{t.icon}}</span> {{t.label}}
        </button>
      </div>

      <div *ngIf="loading" class="loading-overlay"><div class="spinner"></div></div>

      <!-- Decisions list -->
      <div *ngIf="activeTab === 'decisions' && !loading">
        <div class="card" style="padding:0;overflow:hidden;">
          <table class="data-table">
            <thead>
              <tr>
                <th>Incident</th>
                <th>Action</th>
                <th>Confiance</th>
                <th>Raisonnement</th>
                <th>Date</th>
                <th></th>
              </tr>
            </thead>
            <tbody>
              <tr *ngIf="decisions.length === 0">
                <td colspan="6" style="text-align:center;padding:40px;color:var(--text-faint);">Aucune décision</td>
              </tr>
              <tr *ngFor="let d of decisions">
                <td style="font-family:var(--font-mono);font-size:10px;color:var(--accent-blue);">
                  {{d.incidentId?.substring(0,20)}}...
                </td>
                <td>
                  <span class="badge" [class]="d.action === 'APPROVE' ? 'info' : 'high'">{{d.action}}</span>
                </td>
                <td>
                  <div style="display:flex;align-items:center;gap:6px;">
                    <div class="mini-bar">
                      <div [style.width]="(d.confidence||0)*100+'%'"
                           [style.background]="getConfidenceColor(d.confidence)"></div>
                    </div>
                    <span style="font-size:10px;font-family:var(--font-mono);color:var(--text-muted);">
                      {{((d.confidence||0)*100)|number:'1.0-0'}}%
                    </span>
                  </div>
                </td>
                <td style="max-width:200px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:11px;">
                  {{d.reasoning}}
                </td>
                <td style="font-family:var(--font-mono);font-size:10px;">
                  {{d.createdAt | date:'dd/MM HH:mm'}}
                </td>
                <td>
                  <a [routerLink]="['/incidents', d.incidentId]" class="btn btn-secondary btn-sm">→</a>
                </td>
              </tr>
            </tbody>
          </table>
        </div>
      </div>

      <!-- Reports list -->
      <div *ngIf="activeTab !== 'decisions' && !loading">
        <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(320px,1fr));gap:12px;">
          <div *ngIf="reports.length === 0" style="grid-column:1/-1;"
               class="empty-state"><div class="empty-title">Aucun rapport</div></div>

          <div *ngFor="let r of reports" class="report-card">
            <div class="report-header">
              <span class="agent-pill" [style.color]="getAgentColor(r.agentType)"
                    [style.background]="getAgentColor(r.agentType)+'11'">
                {{getAgentIcon(r.agentType)}} {{getAgentLabel(r.agentType)}}
              </span>
              <div style="display:flex;align-items:center;gap:6px;">
                <div class="mini-bar">
                  <div [style.width]="(r.confidence||0)*100+'%'"
                       [style.background]="getAgentColor(r.agentType)"></div>
                </div>
                <span style="font-size:10px;font-family:var(--font-mono);color:var(--text-muted);">
                  {{((r.confidence||0)*100)|number:'1.0-0'}}%
                </span>
              </div>
            </div>
            <div class="report-body">{{r.analysis || r.content}}</div>
            <div class="report-footer">
              <span style="font-family:var(--font-mono);font-size:10px;color:var(--text-faint);">
                {{r.createdAt | date:'dd/MM/yyyy HH:mm'}}
              </span>
              <a [routerLink]="['/incidents', r.incidentId]" class="btn btn-secondary btn-sm">Incident →</a>
            </div>
          </div>
        </div>
      </div>
    </div>
  `,
  styles: [`
    .agent-tabs { display: flex; gap: 8px; flex-wrap: wrap; }

    .agent-tab {
      display: flex;
      align-items: center;
      gap: 6px;
      padding: 7px 14px;
      border-radius: var(--radius-md);
      font-size: 12px;
      color: var(--text-muted);
      background: var(--bg-secondary);
      border: 1px solid var(--border);
      cursor: pointer;
      transition: all 0.15s;

      &:hover { border-color: var(--border-light); color: var(--text-secondary); }
      &.active {
        background: var(--tab-color, var(--accent-blue));
        color: #080c14;
        border-color: transparent;
      }
    }

    .mini-bar {
      width: 50px; height: 3px;
      background: var(--border);
      border-radius: 2px;
      overflow: hidden;
      div { height: 100%; border-radius: 2px; }
    }

    .report-card {
      background: var(--bg-secondary);
      border: 1px solid var(--border);
      border-radius: var(--radius-lg);
      padding: 16px;
      display: flex;
      flex-direction: column;
      gap: 10px;
      transition: border-color 0.2s;
      &:hover { border-color: var(--border-light); }
    }

    .report-header {
      display: flex;
      align-items: center;
      justify-content: space-between;
    }

    .agent-pill {
      font-size: 11px;
      font-weight: 600;
      padding: 3px 10px;
      border-radius: 20px;
      font-family: var(--font-mono);
    }

    .report-body {
      font-size: 12px;
      color: var(--text-secondary);
      line-height: 1.6;
      overflow: hidden;
      display: -webkit-box;
      -webkit-line-clamp: 4;
      -webkit-box-orient: vertical;
    }

    .report-footer {
      display: flex;
      align-items: center;
      justify-content: space-between;
    }
  `]
})
export class AnalysisComponent implements OnInit {
  reports: any[]   = [];
  decisions: any[] = [];
  loading = false;
  activeTab = 'decisions';

  tabs = [
    { key: 'decisions',   label: 'Décisions Judge', icon: '▣', color: '#f59e0b' },
    { key: 'ROOT_CAUSE',  label: 'Root Cause',       icon: '◈', color: '#38bdf8' },
    { key: 'SECURITY',    label: 'Security Risk',     icon: '⬡', color: '#e24b4a' },
    { key: 'REMEDIATION', label: 'Remediation',       icon: '◆', color: '#22c55e' },
  ];

  constructor(private api: ApiService, private toast: ToastService) {}

  ngOnInit() { this.load(); }

  load() {
    this.loading = true;
    if (this.activeTab === 'decisions') {
      this.api.getDecisions().subscribe({
        next: d => { this.decisions = d; this.loading = false; },
        error: () => { this.loading = false; }
      });
    } else {
      this.api.getReports({ agentType: this.activeTab }).subscribe({
        next: r => { this.reports = r; this.loading = false; },
        error: () => { this.loading = false; }
      });
    }
  }

  getAgentColor(t: string) {
    const m: any = { ROOT_CAUSE: '#38bdf8', SECURITY: '#e24b4a', REMEDIATION: '#22c55e', JUDGE: '#f59e0b' };
    return m[t] || '#7ba8c8';
  }

  getAgentIcon(t: string) {
    const m: any = { ROOT_CAUSE: '◈', SECURITY: '⬡', REMEDIATION: '◆', JUDGE: '▣' };
    return m[t] || '◉';
  }

  getAgentLabel(t: string) {
    const m: any = { ROOT_CAUSE: 'Root Cause', SECURITY: 'Security Risk', REMEDIATION: 'Remediation', JUDGE: 'Judge' };
    return m[t] || t;
  }

  getConfidenceColor(c: number) {
    if (c >= 0.8) return 'var(--accent-green)';
    if (c >= 0.6) return 'var(--accent-orange)';
    return 'var(--accent-red)';
  }
}
